// Card container (rounded, dark bg, subtle lime border)
static lv_obj_t * mk_card(lv_obj_t * p, lv_coord_t y, lv_coord_t h)
{
    lv_obj_t * card = lv_obj_create(p);
    lv_obj_set_size(card, TAB_USE_W, h);
    lv_obj_set_pos(card, TAB_MARG, y);
    lv_obj_clear_flag(card, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_bg_color(card,    lv_color_hex(TV_CARD),   LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_opa(card,      LV_OPA_COVER,            LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_color(card, lv_color_hex(TV_LIME),  LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_width(card, 1,                      LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_opa(card,   LV_OPA_30,              LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_radius(card,       12,                     LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_pad_all(card,      CARD_PAD,               LV_PART_MAIN | LV_STATE_DEFAULT);
    return card;
}

// Bordered (outline-only) button used inside cards
static lv_obj_t * mk_outline_btn(lv_obj_t * p,
                                  lv_coord_t x, lv_coord_t y,
                                  lv_coord_t w, lv_coord_t h,
                                  const char * text, uint32_t color, lv_event_cb_t cb)
{
    lv_obj_t * btn = lv_btn_create(p);
    lv_obj_set_size(btn, w, h);
    lv_obj_set_pos(btn, x, y);
    lv_obj_set_style_bg_color(btn,    lv_color_hex(TV_CARD),  LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_opa(btn,      LV_OPA_COVER,           LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_opa(btn,      LV_OPA_70,              LV_PART_MAIN | LV_STATE_PRESSED);
    lv_obj_set_style_border_color(btn, lv_color_hex(color),   LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_width(btn, 2,                     LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_opa(btn,   LV_OPA_COVER,          LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_radius(btn,       20,                    LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_outline_width(btn, 0,                    LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_outline_width(btn, 0,                    LV_PART_MAIN | LV_STATE_FOCUSED);
    lv_obj_set_style_shadow_width(btn,  0,                    LV_PART_MAIN | LV_STATE_DEFAULT);

    lv_obj_t * lbl = lv_label_create(btn);
    lv_label_set_text(lbl, text);
    lv_obj_set_style_text_color(lbl, lv_color_hex(color), 0);
    lv_obj_set_style_text_font(lbl,  &ui_font_name_14, 0);
    lv_obj_center(lbl);

    if(cb) lv_obj_add_event_cb(btn, cb, LV_EVENT_CLICKED, NULL);
    return btn;
}

static void _tab_set_date_cb(lv_event_t * e)
{
    if(lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    _ui_screen_change(&ui_date_picker, LV_SCR_LOAD_ANIM_FADE_ON, 300, 0,
                      &ui_date_picker_screen_init);
}

static void _tab_set_time_cb(lv_event_t * e)
{
    if(lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    _ui_screen_change(&ui_time_picker, LV_SCR_LOAD_ANIM_FADE_ON, 300, 0,
                      &ui_time_picker_screen_init);
}

// ── Tab page builders ─────────────────────────────────────────────────────

static void build_tab_display(lv_obj_t * page)
{
    // Fixed layout — NO vertical scroll
    lv_obj_set_style_bg_opa(page,     LV_OPA_TRANSP, 0);
    lv_obj_set_style_pad_all(page,    0, 0);
    lv_obj_set_style_border_width(page, 0, 0);
    lv_obj_set_scroll_dir(page,       LV_DIR_NONE);

    // Title + divider
    mk_lbl(page, "DISPLAY", TAB_MARG, 2, TV_LIME, &ui_font_name_24);
    lv_obj_t * dsp_div = lv_obj_create(page);
    lv_obj_set_size(dsp_div, TAB_PG_W - 2*TAB_MARG, 1);
    lv_obj_set_pos(dsp_div, TAB_MARG, 32);
    lv_obj_set_style_bg_color(dsp_div,    lv_color_hex(TV_LIME), 0);
    lv_obj_set_style_bg_opa(dsp_div,      LV_OPA_30, 0);
    lv_obj_set_style_border_width(dsp_div, 0, 0);
    lv_obj_set_style_radius(dsp_div,      0, 0);
    lv_obj_set_style_pad_all(dsp_div,     0, 0);

    // Section header
    mk_lbl(page, "BRIGHTNESS", TAB_MARG, 36, TV_MUTED, &ui_font_name_14);

    int cur_bright = sys_get_brightness();
    int cur_led    = sys_get_led();

    // ── Card 1: LCD Backlight (y=54, h=72) ──────────────────────────────
    // pad_bottom=0 → content 64px; slider y=36, knob_bottom=62 ✓
    lv_obj_t * c1 = mk_card(page, 54, 72);
    lv_obj_set_style_pad_bottom(c1, 0, LV_PART_MAIN | LV_STATE_DEFAULT);

    lv_obj_t * lbl_bl_val = lv_label_create(c1);
    lv_label_set_text_fmt(lbl_bl_val, "%d%%", cur_bright);
    lv_obj_set_pos(lbl_bl_val, 0, 2);
    lv_obj_set_width(lbl_bl_val, CARD_INN);
    lv_obj_set_style_text_align(lbl_bl_val, LV_TEXT_ALIGN_RIGHT, 0);
    lv_obj_set_style_text_color(lbl_bl_val, lv_color_hex(TV_LIME), 0);
    lv_obj_set_style_text_font(lbl_bl_val,  &ui_font_name_24, 0);

    mk_lbl(c1, "LCD Backlight", 0, 2, TV_TEXT, &ui_font_name_14);
    lv_obj_t * sl_bl = mk_display_slider(c1, 36, cur_bright, lbl_bl_val);
    lv_obj_add_event_cb(sl_bl, tab_bright_cb, LV_EVENT_VALUE_CHANGED, NULL);

    // ── Card 2: LED Indicator (y=132, h=72) ─────────────────────────────
    lv_obj_t * c2 = mk_card(page, 132, 72);
    lv_obj_set_style_pad_bottom(c2, 0, LV_PART_MAIN | LV_STATE_DEFAULT);

    lv_obj_t * lbl_led_val = lv_label_create(c2);
    lv_label_set_text_fmt(lbl_led_val, "%d%%", cur_led);
    lv_obj_set_pos(lbl_led_val, 0, 2);
    lv_obj_set_width(lbl_led_val, CARD_INN);
    lv_obj_set_style_text_align(lbl_led_val, LV_TEXT_ALIGN_RIGHT, 0);
    lv_obj_set_style_text_color(lbl_led_val, lv_color_hex(TV_LIME), 0);
    lv_obj_set_style_text_font(lbl_led_val,  &ui_font_name_24, 0);

    mk_lbl(c2, "LED Indicator", 0, 2, TV_TEXT, &ui_font_name_14);
    lv_obj_t * sl_led = mk_display_slider(c2, 36, cur_led, lbl_led_val);
    lv_obj_add_event_cb(sl_led, tab_led_cb, LV_EVENT_VALUE_CHANGED, NULL);
}

