static void build_tab_system(lv_obj_t * page)
{
    // Page itself is NOT scrollable — title stays fixed
    lv_obj_set_style_bg_opa(page,      LV_OPA_TRANSP, 0);
    lv_obj_set_style_pad_all(page,     0, 0);
    lv_obj_set_style_border_width(page, 0, 0);
    lv_obj_set_scroll_dir(page,        LV_DIR_NONE);

    // ── Fixed header: title + divider ────────────────────────────────────────
    mk_lbl(page, "SYSTEM", TAB_MARG, 4, TV_LIME, &ui_font_name_24);
    lv_obj_t * sys_div = lv_obj_create(page);
    lv_obj_set_size(sys_div, TAB_PG_W - 2*TAB_MARG, 1);
    lv_obj_set_pos(sys_div, TAB_MARG, 34);
    lv_obj_set_style_bg_color(sys_div, lv_color_hex(TV_LIME), 0);
    lv_obj_set_style_bg_opa(sys_div,   LV_OPA_30, 0);
    lv_obj_set_style_border_width(sys_div, 0, 0);
    lv_obj_set_style_radius(sys_div,   0, 0);
    lv_obj_set_style_pad_all(sys_div,  0, 0);

    // ── Scrollable content sub-container (below header) ──────────────────────
    lv_obj_t * sc = lv_obj_create(page);
    lv_obj_set_size(sc, TAB_PG_W, 241 - 38);
    lv_obj_set_pos(sc, 0, 38);
    lv_obj_set_scroll_dir(sc, LV_DIR_VER);
    lv_obj_set_scrollbar_mode(sc, LV_SCROLLBAR_MODE_AUTO);
    lv_obj_set_style_bg_opa(sc,        LV_OPA_TRANSP, 0);
    lv_obj_set_style_pad_all(sc,       0, 0);
    lv_obj_set_style_pad_bottom(sc,    40, 0);
    lv_obj_set_style_border_width(sc,  0, 0);
    lv_obj_set_style_radius(sc,        0, 0);

    int y = 4;

    // ── POWER ────────────────────────────────────────────────────────────────
    mk_lbl(sc, "POWER", TAB_MARG, y, TV_MUTED, &ui_font_name_14);
    y += 20;

    lv_obj_t * c_bat = mk_card(sc, y, 70);
    mk_lbl(c_bat, "Battery", 0, 0, TV_TEXT, &ui_font_name_14);
    s_sys_bat_status = mk_lbl(c_bat, "discharging", 0, 18, TV_MUTED, &ui_font_name_14);

    s_sys_bat_pct_lbl = lv_label_create(c_bat);
    lv_label_set_text(s_sys_bat_pct_lbl, "--");
    lv_obj_set_pos(s_sys_bat_pct_lbl, 0, 0);
    lv_obj_set_width(s_sys_bat_pct_lbl, CARD_INN);
    lv_obj_set_style_text_align(s_sys_bat_pct_lbl, LV_TEXT_ALIGN_RIGHT, 0);
    lv_obj_set_style_text_color(s_sys_bat_pct_lbl, lv_color_hex(TV_LIME), 0);
    lv_obj_set_style_text_font(s_sys_bat_pct_lbl, &ui_font_name_24, 0);

    lv_obj_t * bat_body = lv_obj_create(c_bat);
    lv_obj_set_size(bat_body, 44, 22);
    lv_obj_set_pos(bat_body, CARD_INN - 52, 28);
    lv_obj_clear_flag(bat_body, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_bg_color(bat_body, lv_color_hex(TV_CARD), 0);
    lv_obj_set_style_bg_opa(bat_body, LV_OPA_COVER, 0);
    lv_obj_set_style_border_color(bat_body, lv_color_hex(TV_LIME), 0);
    lv_obj_set_style_border_width(bat_body, 2, 0);
    lv_obj_set_style_radius(bat_body, 4, 0);
    lv_obj_set_style_pad_all(bat_body, 0, 0);
    // bat_fill as sibling on c_bat, manually positioned 4px inside bat_body border
    s_sys_bat_fill = lv_obj_create(c_bat);
    lv_obj_set_size(s_sys_bat_fill, 36, 14);   /* initial 100%; _sys_bat_refresh updates width */
    lv_obj_set_pos(s_sys_bat_fill, CARD_INN - 52 + 4, 32);
    lv_obj_clear_flag(s_sys_bat_fill, LV_OBJ_FLAG_SCROLLABLE | LV_OBJ_FLAG_CLICKABLE);
    lv_obj_set_style_bg_color(s_sys_bat_fill, lv_color_hex(TV_LIME), 0);
    lv_obj_set_style_bg_opa(s_sys_bat_fill, LV_OPA_COVER, 0);
    lv_obj_set_style_border_width(s_sys_bat_fill, 0, 0);
    lv_obj_set_style_radius(s_sys_bat_fill, 2, 0);
    lv_obj_set_style_pad_all(s_sys_bat_fill, 0, 0);
    lv_obj_set_style_shadow_width(s_sys_bat_fill, 0, 0);
    lv_obj_set_style_outline_width(s_sys_bat_fill, 0, 0);
    lv_obj_t * bat_nub = lv_obj_create(c_bat);
    lv_obj_set_size(bat_nub, 6, 10);
    lv_obj_set_pos(bat_nub, CARD_INN - 52 + 45, 34);
    lv_obj_clear_flag(bat_nub, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_bg_color(bat_nub, lv_color_hex(TV_LIME), 0);
    lv_obj_set_style_bg_opa(bat_nub, LV_OPA_COVER, 0);
    lv_obj_set_style_border_width(bat_nub, 0, 0);
    lv_obj_set_style_radius(bat_nub, 2, 0);
    lv_obj_set_style_pad_all(bat_nub, 0, 0);

    /* Prime display with real battery data, then refresh every second */
    _sys_bat_refresh(NULL);
    if (!s_sys_bat_timer) {
        s_sys_bat_timer = lv_timer_create(_sys_bat_refresh, 1000, NULL);
    }
    y += 70 + 8;

    lv_obj_t * c_rb = mk_card(sc, y, 66);
    mk_lbl(c_rb, "Reboot", 0, 0, TV_TEXT, &ui_font_name_14);
    mk_lbl(c_rb, "soft restart", 0, 30, TV_MUTED, &ui_font_name_14);
    mk_outline_btn(c_rb, CARD_INN - 90, 7, 90, 36, "Reboot", 0xBEE700, tab_reboot_cb);
    y += 66 + 8;

    // ── STORAGE ──────────────────────────────────────────────────────────────
    mk_lbl(sc, "STORAGE", TAB_MARG, y, TV_MUTED, &ui_font_name_14);
    y += 20;

    {
        uint64_t sd_total = (uint64_t)ui_sd_total_bytes();
        uint64_t sd_used  = (uint64_t)ui_sd_used_bytes();
        int sd_pct = (sd_total > 0) ? (int)((sd_used * 100ULL) / sd_total) : 0;
        char sd_info[40];
        if(sd_total == 0) {
            lv_snprintf(sd_info, sizeof(sd_info), "not mounted");
        } else {
            uint32_t u_mb = (uint32_t)(sd_used  / 1048576UL);
            uint32_t t_mb = (uint32_t)(sd_total / 1048576UL);
            if(t_mb >= 1024)
                lv_snprintf(sd_info, sizeof(sd_info), "%u.%u / %u.%u GB",
                            u_mb / 1024, (u_mb % 1024) * 10 / 1024,
                            t_mb / 1024, (t_mb % 1024) * 10 / 1024);
            else
                lv_snprintf(sd_info, sizeof(sd_info), "%u / %u MB", u_mb, t_mb);
        }

        lv_obj_t * c_sd = mk_card(sc, y, 68);
        mk_lbl(c_sd, "SD Card", 0, 0, TV_TEXT, &ui_font_name_14);
        mk_bar(c_sd, 0, 20, CARD_INN, sd_pct, TV_ORANGE);
        {
            lv_obj_t * l = lv_label_create(c_sd);
            lv_label_set_text(l, sd_info);
            lv_obj_set_pos(l, 0, 38);
            lv_obj_set_width(l, CARD_INN);
            lv_obj_set_style_text_align(l, LV_TEXT_ALIGN_RIGHT, 0);
            lv_obj_set_style_text_color(l, lv_color_hex(TV_MUTED), 0);
            lv_obj_set_style_text_font(l, &ui_font_name_14, 0);
        }
        y += 68 + 8;
    }

    // ── FLASH / NVS ──────────────────────────────────────────────────────────
    mk_lbl(sc, "FLASH", TAB_MARG, y, TV_MUTED, &ui_font_name_14);
    y += 20;

    {
        nvs_stats_t nst = {};
        nvs_get_stats(NULL, &nst);   /* NULL = default NVS partition */
        int nvs_pct = (nst.total_entries > 0)
                      ? (int)((nst.used_entries * 100u) / nst.total_entries) : 0;
        char nvs_info[40];
        lv_snprintf(nvs_info, sizeof(nvs_info), "%u / %u entries",
                    (unsigned)nst.used_entries, (unsigned)nst.total_entries);

        lv_obj_t * c_nvs = mk_card(sc, y, 68);
        mk_lbl(c_nvs, "NVS Config", 0, 0, TV_TEXT, &ui_font_name_14);
        mk_bar(c_nvs, 0, 20, CARD_INN, nvs_pct, TV_LIME);
        {
            lv_obj_t * l = lv_label_create(c_nvs);
            lv_label_set_text(l, nvs_info);
            lv_obj_set_pos(l, 0, 38);
            lv_obj_set_width(l, CARD_INN);
            lv_obj_set_style_text_align(l, LV_TEXT_ALIGN_RIGHT, 0);
            lv_obj_set_style_text_color(l, lv_color_hex(TV_MUTED), 0);
            lv_obj_set_style_text_font(l, &ui_font_name_14, 0);
        }
        y += 68 + 8;
    }

    // ── MAINTENANCE ──────────────────────────────────────────────────────────
    mk_lbl(sc, "MAINTENANCE", TAB_MARG, y, TV_MUTED, &ui_font_name_14);
    y += 20;

    lv_obj_t * c_fr = mk_card(sc, y, 84);
    mk_lbl(c_fr, "Factory Reset", 0, 0, TV_TEXT, &ui_font_name_14);
    mk_lbl(c_fr, "erase all", 0, 30, TV_MUTED, &ui_font_name_14);
    mk_lbl(c_fr, "settings", 0, 48, TV_MUTED, &ui_font_name_14);
    mk_outline_btn(c_fr, CARD_INN - 90, 10, 90, 44, "Reset", TV_DANGER, tab_factory_reset_cb);
    y += 84 + 8;

}

// ── Screen init / destroy ─────────────────────────────────────────────────

void ui_tabview_screen_init(void)
{
    ui_tabview = lv_obj_create(NULL);
    lv_obj_clear_flag(ui_tabview, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_bg_color(ui_tabview, lv_color_hex(TV_BG), 0);
    lv_obj_set_style_bg_opa(ui_tabview, LV_OPA_COVER, 0);
    lv_obj_set_style_shadow_width(ui_tabview, 0, 0);
    lv_obj_set_style_outline_width(ui_tabview, 0, 0);

    // ── Background image ─────────────────────────────────────────────────
    lv_obj_t * tv_bg = lv_img_create(ui_tabview);
    lv_img_set_src(tv_bg, &ui_img_background_v_png);
    lv_obj_set_width(tv_bg, LV_SIZE_CONTENT);
    lv_obj_set_height(tv_bg, LV_SIZE_CONTENT);
    lv_obj_set_align(tv_bg, LV_ALIGN_CENTER);
    lv_obj_add_flag(tv_bg, LV_OBJ_FLAG_ADV_HITTEST);
    lv_obj_clear_flag(tv_bg, LV_OBJ_FLAG_SCROLLABLE);

    // ── Tabview ───────────────────────────────────────────────────────────
    ui_tabview_settings = lv_tabview_create(ui_tabview, LV_DIR_LEFT, TAB_BAR_W);
    lv_obj_set_size(ui_tabview_settings, 320, 241);
    lv_obj_set_pos(ui_tabview_settings, 0, -1);
    lv_obj_clear_flag(ui_tabview_settings, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_bg_opa(ui_tabview_settings, LV_OPA_TRANSP, 0);
    lv_obj_set_style_pad_all(ui_tabview_settings, 0, 0);
    lv_obj_set_style_border_width(ui_tabview_settings, 0, 0);
    lv_obj_set_style_shadow_width(ui_tabview_settings, 0, 0);
    lv_obj_set_style_outline_width(ui_tabview_settings, 0, 0);

    lv_obj_t * cont = lv_tabview_get_content(ui_tabview_settings);
    lv_obj_set_style_bg_opa(cont, LV_OPA_TRANSP, 0);
    lv_obj_set_style_pad_all(cont, 0, 0);

    // ── Tab button bar styling ────────────────────────────────────────────
    lv_obj_t * tab_btns = lv_tabview_get_tab_btns(ui_tabview_settings);

    lv_obj_set_style_bg_opa(tab_btns,    LV_OPA_TRANSP,          LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_width(tab_btns, 0,                   LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_side(tab_btns,  LV_BORDER_SIDE_NONE, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_pad_all(tab_btns,   0,                      LV_PART_MAIN | LV_STATE_DEFAULT);

    lv_obj_set_style_bg_opa(tab_btns,    LV_OPA_TRANSP,          LV_PART_ITEMS | LV_STATE_DEFAULT);
    lv_obj_set_style_text_color(tab_btns, lv_color_hex(TV_MUTED), LV_PART_ITEMS | LV_STATE_DEFAULT);
    lv_obj_set_style_text_font(tab_btns, &ui_font_name_14,        LV_PART_ITEMS | LV_STATE_DEFAULT);
    lv_obj_set_style_border_width(tab_btns, 0,                   LV_PART_ITEMS | LV_STATE_DEFAULT);
    lv_obj_set_style_shadow_width(tab_btns, 0,                   LV_PART_ITEMS | LV_STATE_DEFAULT);
    lv_obj_set_style_outline_width(tab_btns, 0,                  LV_PART_ITEMS | LV_STATE_DEFAULT);

    lv_obj_set_style_bg_color(tab_btns,  lv_color_hex(TV_LIME),  LV_PART_ITEMS | LV_STATE_CHECKED);
    lv_obj_set_style_bg_opa(tab_btns,    LV_OPA_COVER,           LV_PART_ITEMS | LV_STATE_CHECKED);
    lv_obj_set_style_text_color(tab_btns, lv_color_hex(TV_INK),  LV_PART_ITEMS | LV_STATE_CHECKED);
    lv_obj_set_style_radius(tab_btns,    8,                       LV_PART_ITEMS | LV_STATE_CHECKED);
    lv_obj_set_style_border_width(tab_btns, 0,                   LV_PART_ITEMS | LV_STATE_CHECKED);
    lv_obj_set_style_shadow_width(tab_btns, 0,                     LV_PART_ITEMS | LV_STATE_CHECKED);

    // ── Add tabs + build content ──────────────────────────────────────────
    ui_TabPage1 = lv_tabview_add_tab(ui_tabview_settings, "Display");
    ui_TabPage2 = lv_tabview_add_tab(ui_tabview_settings, "Sound");
    ui_TabPage3 = lv_tabview_add_tab(ui_tabview_settings, "Connect");
    ui_TabPage4 = lv_tabview_add_tab(ui_tabview_settings, "Time");
    ui_TabPage5 = lv_tabview_add_tab(ui_tabview_settings, "System");

    build_tab_display(ui_TabPage1);
    build_tab_sound(ui_TabPage2);
    build_tab_connect(ui_TabPage3);
    build_tab_time(ui_TabPage4);
    build_tab_system(ui_TabPage5);

    // ── Bottom key bar ────────────────────────────────────────────────────
    ui_tab_key_prompts_bg = lv_img_create(ui_tabview);
    lv_img_set_src(ui_tab_key_prompts_bg, &ui_img_key_prompts_bg_png);
    lv_obj_set_width(ui_tab_key_prompts_bg,  LV_SIZE_CONTENT);
    lv_obj_set_height(ui_tab_key_prompts_bg, LV_SIZE_CONTENT);
    lv_obj_set_pos(ui_tab_key_prompts_bg, 168, 204);
    lv_obj_add_flag(ui_tab_key_prompts_bg, LV_OBJ_FLAG_ADV_HITTEST);
    lv_obj_clear_flag(ui_tab_key_prompts_bg, LV_OBJ_FLAG_SCROLLABLE);

    ui_tab_key_a_bg = lv_img_create(ui_tabview);
    lv_img_set_src(ui_tab_key_a_bg, &ui_img_key_a_png);
    lv_obj_set_width(ui_tab_key_a_bg,  LV_SIZE_CONTENT);
    lv_obj_set_height(ui_tab_key_a_bg, LV_SIZE_CONTENT);
    lv_obj_set_pos(ui_tab_key_a_bg, 171, 207);
    lv_obj_add_flag(ui_tab_key_a_bg, LV_OBJ_FLAG_ADV_HITTEST | LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(ui_tab_key_a_bg, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_event_cb(ui_tab_key_a_bg, tab_key_a_cb, LV_EVENT_CLICKED, NULL);

    ui_tab_key_b_bg = lv_img_create(ui_tabview);
    lv_img_set_src(ui_tab_key_b_bg, &ui_img_key_b_png);
    lv_obj_set_width(ui_tab_key_b_bg,  LV_SIZE_CONTENT);
    lv_obj_set_height(ui_tab_key_b_bg, LV_SIZE_CONTENT);
    lv_obj_set_pos(ui_tab_key_b_bg, 241, 207);
    lv_obj_add_flag(ui_tab_key_b_bg, LV_OBJ_FLAG_ADV_HITTEST | LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(ui_tab_key_b_bg, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_event_cb(ui_tab_key_b_bg, tab_key_b_cb, LV_EVENT_CLICKED, NULL);

    ui_tab_key_a_save = lv_label_create(ui_tabview);
    lv_obj_set_pos(ui_tab_key_a_save, 194, 211);
    lv_label_set_text(ui_tab_key_a_save, "Home");
    lv_obj_set_style_text_color(ui_tab_key_a_save, lv_color_hex(0x000000), 0);
    lv_obj_set_style_text_font(ui_tab_key_a_save,  &ui_font_name_14, 0);

    ui_tab_key_a_back = lv_label_create(ui_tabview);
    lv_obj_set_pos(ui_tab_key_a_back, 265, 211);
    lv_label_set_text(ui_tab_key_a_back, "Back");
    lv_obj_set_style_text_color(ui_tab_key_a_back, lv_color_hex(0x000000), 0);
    lv_obj_set_style_text_font(ui_tab_key_a_back,  &ui_font_name_14, 0);
}

void ui_tabview_screen_destroy(void)
{
    if(s_time_timer)    { lv_timer_del(s_time_timer);    s_time_timer    = NULL; }
    if(s_sys_bat_timer) { lv_timer_del(s_sys_bat_timer); s_sys_bat_timer = NULL; }
    s_lbl_date        = NULL;
    s_lbl_time_str    = NULL;
    s_sys_bat_pct_lbl = NULL;
    s_sys_bat_status  = NULL;
    s_sys_bat_fill    = NULL;

    if(ui_tabview) lv_obj_del(ui_tabview);

    ui_tabview            = NULL;
    ui_tabview_settings   = NULL;
    ui_TabPage1           = NULL;
    ui_TabPage2           = NULL;
    ui_TabPage3           = NULL;
    ui_TabPage4           = NULL;
    ui_TabPage5           = NULL;
    ui_tab_key_prompts_bg = NULL;
    ui_tab_key_a_bg       = NULL;
    ui_tab_key_b_bg       = NULL;
    ui_tab_key_a_save     = NULL;
    ui_tab_key_a_back     = NULL;
}
